using System;using System.IO;using System.Linq;using System.Collections.Generic;
using Elevator.Core.Project;using Elevator.Solution.Bridge;
public class StepExportTests
{
 static List<object> checks=new List<object>();static string folder,bin;
 static void Check(bool value,string text){if(!value)throw new Exception(text);}
 static void Near(double a,double b,string name){Check(Math.Abs(a-b)<.001,name+": "+a+" vs "+b);}
 // Reflection/serializer field discovery order can change; compare all JSON values, not key order.
 static string Canonical(object v){var j=new System.Web.Script.Serialization.JavaScriptSerializer();var map=v as IDictionary<string,object>;if(map!=null)return "{"+String.Join(",",map.Keys.OrderBy(k=>k,StringComparer.Ordinal).Select(k=>j.Serialize(k)+":"+Canonical(map[k])))+"}";var list=v as System.Collections.IEnumerable;if(list!=null&&!(v is string))return "["+String.Join(",",list.Cast<object>().Select(Canonical))+"]";return j.Serialize(v);}
 static void Test(string name,Action action){try{action();checks.Add(new{Name=name,Status="PASS"});}catch(Exception e){checks.Add(new{Name=name,Status="FAIL",Error=e.ToString()});}Wire.Write(Path.Combine(folder,"step-unit-tests.json"),checks);}
 static ElevatorProject Project(){var p=ProjectJson.Deserialize(File.ReadAllText(Path.Combine(bin,"reviewed-example.elevator.json")));foreach(var f in p.Building.Floors.Take(p.Building.Floors.Count-1))f.HeightToNextMm=3000;return p;}
 static StepModelParameters Map(ElevatorProject p){ElevatorDesignResult d;return StepInputFactory.Create(p,Wire.Read<DesignContext>(Path.Combine(bin,"reviewed-context.json")),Wire.Read<StepModelParameters>(Path.Combine(bin,"preliminary-3d-reference.json")),out d);}
 public static int Main(string[] args)
 {
  bin=Path.GetFullPath(args[0]);folder=Path.GetFullPath(args[1]);Directory.CreateDirectory(folder);
  Test("Reference model dimensions preserved",()=>{var p=Project();string snapshot=ProjectJson.Serialize(p);var actual=Map(p);var reference=Wire.Read<StepModelParameters>(Path.Combine(bin,"preliminary-3d-reference.json"));foreach(var f in typeof(StepModelParameters).GetFields().Where(f=>f.FieldType==typeof(double)))Near((double)f.GetValue(actual),(double)f.GetValue(reference),f.Name);var j=new System.Web.Script.Serialization.JavaScriptSerializer();Check(Canonical(j.DeserializeObject(snapshot))==Canonical(j.DeserializeObject(ProjectJson.Serialize(p))),"Input values were modified");File.WriteAllText(Path.Combine(folder,"representative.elevator.json"),snapshot);Wire.Write(Path.Combine(folder,"baseline-parameters.json"),actual);});
  Test("Current SW SD shared selection and machine datums",()=>{var p=Project();p.Shaft.WidthMm=1600;p.Shaft.DepthMm=1800;var m=Map(p);Near(m.CarWidth,1200,"Car width");Near(m.CarDepth,1400,"Car depth");Near(m.CarDBG,1300,"Car DBG");Near(m.DoorWidth,1000,"Door");Near(m.DeflectorDiameter,400,"Deflector");Near(m.TractionY,m.CarRow+260,"Traction datum");Near(m.DeflectorY,m.CwRow-200,"Deflector datum");Near(m.MachineBaseX,870,"Machine translated with center");Near(m.GovernorY,m.CarRow+200+125,"Governor offset");Check(m.ConcreteHeight>=350&&m.ConcreteHeight<=1000,"Support range");});
  Test("Unequal floors NO STOP and displayed car pose",()=>{var p=Project();p.Building.Floors[0].HeightToNextMm=3100;p.Building.Floors[1].HeightToNextMm=2800;p.Building.Floors[2].IsServed=false;p.Car.DisplayFloorId=p.Building.Floors[3].FloorId;var m=Map(p);Near(m.FloorElevations[2],5900,"Unequal elevation");Check(!m.ServedFloors[2],"NO STOP lost");Near(m.CarFloorZ,8900,"Car pose");Near(m.CwBottom,p.Counterweight.ReferenceBottomElevationMm.Value-8900,"CW coordinated pose");});
  Test("Nonblocking D/d failure remains independent",()=>{var p=Project();ElevatorDesignResult d;StepInputFactory.Create(p,Wire.Read<DesignContext>(Path.Combine(bin,"reviewed-context.json")),Wire.Read<StepModelParameters>(Path.Combine(bin,"preliminary-3d-reference.json")),out d);Check(d.CanGenerate&&d.CodeDiameterRatioStatus==ValidationStatus.FAIL&&d.WrapAngleStatus==ValidationStatus.PASS,"Statuses coupled");});
  Test("Unsupported machine rejected without geometry substitution",()=>{var p=Project();p.Machine.TractionSheavePitchDiameterMm=500;bool rejected=false;try{Map(p);}catch(ArgumentException){rejected=true;}Check(rejected,"Unreviewed machine accepted");});
  Test("Incomplete export package gives clear dependency error",()=>{bool rejected=false;try{new StepExportClient(folder).CheckDependencies();}catch(FileNotFoundException e){rejected=e.Message.Contains("package is incomplete");}Check(rejected,"Missing worker not explained");});
  Test("Existing STEP preserved without replacement consent",()=>{var path=Path.Combine(folder,"keep.step");File.WriteAllText(path,"original");bool rejected=false;try{new StepExportClient(bin).ExportAsync(Project(),path,false,Console.WriteLine);}catch(IOException){rejected=true;}Check(rejected&&File.ReadAllText(path)=="original","Existing STEP overwritten");});
  if(args.Contains("--export")){Test("Packaged worker real STEP export reopen",()=>{var result=new StepExportClient(bin).ExportAsync(Project(),Path.Combine(folder,"Representative.step"),false,Console.WriteLine).GetAwaiter().GetResult();Check(result.Verification.ReopenedSolidCount==67&&result.Verification.FaultCount==0&&result.Verification.Intersections.Length==0,"Baseline solid regression");Wire.Write(Path.Combine(folder,"export-result.json"),result);});}
  foreach(var r in checks)Console.WriteLine(Wire.Json(r));return checks.Any(r=>Wire.Json(r).Contains("\"FAIL\""))?1:0;
 }
}
